// --- acr_nav.FDb.ctype.Alloc
// Allocate memory for new default row.
// If out of memory, process is killed.
acr_nav::FCtype& acr_nav::ctype_Alloc() {
    acr_nav::FCtype* row = ctype_AllocMaybe();
    if (UNLIKELY(row == NULL)) {
        FatalErrorExit("acr_nav.out_of_mem  field:acr_nav.FDb.ctype  comment:'Alloc failed'");
    }
    return *row;
}

// --- acr_nav.FDb.ctype.AllocMaybe
// Allocate memory for new element. If out of memory, return NULL.
acr_nav::FCtype* acr_nav::ctype_AllocMaybe() {
    acr_nav::FCtype *row = (acr_nav::FCtype*)ctype_AllocMem();
    if (row) {
        new (row) acr_nav::FCtype; // call constructor
    }
    return row;
}

// --- acr_nav.FDb.ctype.InsertMaybe
// Create new row from struct.
// Return pointer to new element, or NULL if insertion failed (due to out-of-memory, duplicate key, etc)
acr_nav::FCtype* acr_nav::ctype_InsertMaybe(const dmmeta::Ctype &value) {
    acr_nav::FCtype *row = &ctype_Alloc(); // if out of memory, process dies. if input error, return NULL.
    ctype_CopyIn(*row,const_cast<dmmeta::Ctype&>(value));
    bool ok = ctype_XrefMaybe(*row); // this may return false
    if (!ok) {
        ctype_RemoveLast(); // delete offending row, any existing xrefs are cleared
        row = NULL; // forget this ever happened
    }
    return row;
}

// --- acr_nav.FDb.ctype.AllocMem
// Allocate space for one element. If no memory available, return NULL.
void* acr_nav::ctype_AllocMem() {
    u64 new_nelems     = _db.ctype_n+1;
    // compute level and index on level
    u64 bsr   = algo::u64_BitScanReverse(new_nelems);
    u64 base  = u64(1)<<bsr;
    u64 index = new_nelems-base;
    void *ret = NULL;
    // if level doesn't exist yet, create it
    acr_nav::FCtype*  lev   = NULL;
    if (bsr < 32) {
        lev = _db.ctype_lary[bsr];
        if (!lev) {
            lev=(acr_nav::FCtype*)algo_lib::malloc_AllocMem(sizeof(acr_nav::FCtype) * (u64(1)<<bsr));
            _db.ctype_lary[bsr] = lev;
        }
    }
    // allocate element from this level
    if (lev) {
        _db.ctype_n = i32(new_nelems);
        ret = lev + index;
    }
    return ret;
}

// --- acr_nav.FDb.ctype.RemoveAll
// Remove all elements from Lary
void acr_nav::ctype_RemoveAll() {
    for (u64 n = _db.ctype_n; n>0; ) {
        n--;
        ctype_qFind(u64(n)).~FCtype(); // destroy last element
        _db.ctype_n = i32(n);
    }
}

// --- acr_nav.FDb.ctype.RemoveLast
// Delete last element of array. Do nothing if array is empty.
void acr_nav::ctype_RemoveLast() {
    u64 n = _db.ctype_n;
    if (n > 0) {
        n -= 1;
        ctype_qFind(u64(n)).~FCtype();
        _db.ctype_n = i32(n);
    }
}

// --- acr_nav.FDb.ctype.InputMaybe
static bool acr_nav::ctype_InputMaybe(dmmeta::Ctype &elem) {
    bool retval = true;
    retval = ctype_InsertMaybe(elem) != nullptr;
    return retval;
}

// --- acr_nav.FDb.ctype.XrefMaybe
// Insert row into all appropriate indices. If error occurs, store error
// in algo_lib::_db.errtext and return false. Caller must Delete or Unref such row.
bool acr_nav::ctype_XrefMaybe(acr_nav::FCtype &row) {
    bool retval = true;
    (void)row;
    acr_nav::FNs* p_ns = acr_nav::ind_ns_Find(ns_Get(row));
    if (UNLIKELY(!p_ns)) {
        algo_lib::ResetErrtext() << "acr_nav.bad_xref  index:acr_nav.FDb.ind_ns" << Keyval("key", ns_Get(row));
        return false;
    }
    // ctype: save pointer to ns
    if (true) { // user-defined insert condition
        row.p_ns = p_ns;
    }
    // insert ctype into index ind_ctype
    if (true) { // user-defined insert condition
        bool success = ind_ctype_InsertMaybe(row);
        if (UNLIKELY(!success)) {
            ch_RemoveAll(algo_lib::_db.errtext);
            algo_lib::_db.errtext << "acr_nav.duplicate_key  xref:acr_nav.FDb.ind_ctype"; // check for duplicate key
            return false;
        }
    }
    // insert ctype into index c_ctype
    if (true) { // user-defined insert condition
        c_ctype_Insert(*p_ns, row);
    }
    return retval;
}

