// --- acr_nav.FDb.ind_ctype.InsertMaybe
// Insert row into hash table. Return true if row is reachable through the hash after the function completes.
bool acr_nav::ind_ctype_InsertMaybe(acr_nav::FCtype& row) {
    bool retval = true; // if already in hash, InsertMaybe returns true
    if (LIKELY(row.ind_ctype_next == (acr_nav::FCtype*)-1)) {// check if in hash already
        row.ind_ctype_hashval = algo::Smallstr100_Hash(0, row.ctype);
        ind_ctype_Reserve(1);
        u32 index = row.ind_ctype_hashval & (_db.ind_ctype_buckets_n - 1);
        acr_nav::FCtype* *prev = &_db.ind_ctype_buckets_elems[index];
        do {
            acr_nav::FCtype* ret = *prev;
            if (!ret) { // exit condition 1: reached the end of the list
                break;
            }
            if ((*ret).ctype == row.ctype) { // exit condition 2: found matching key
                retval = false;
                break;
            }
            prev = &ret->ind_ctype_next;
        } while (true);
        if (retval) {
            row.ind_ctype_next = *prev;
            _db.ind_ctype_n++;
            *prev = &row;
        }
    }
    return retval;
}

// --- acr_nav.FDb.ind_ctype.Remove
// Remove reference to element from hash index. If element is not in hash, do nothing
void acr_nav::ind_ctype_Remove(acr_nav::FCtype& row) {
    if (LIKELY(row.ind_ctype_next != (acr_nav::FCtype*)-1)) {// check if in hash already
        u32 index = row.ind_ctype_hashval & (_db.ind_ctype_buckets_n - 1);
        acr_nav::FCtype* *prev = &_db.ind_ctype_buckets_elems[index]; // addr of pointer to current element
        while (acr_nav::FCtype *next = *prev) {                          // scan the collision chain for our element
            if (next == &row) {        // found it?
                *prev = next->ind_ctype_next; // unlink (singly linked list)
                _db.ind_ctype_n--;
                row.ind_ctype_next = (acr_nav::FCtype*)-1;// not-in-hash
                break;
            }
            prev = &next->ind_ctype_next;
        }
    }
}

// --- acr_nav.FDb.ind_ctype.Reserve
// Reserve enough room in the hash for N more elements. Return success code.
void acr_nav::ind_ctype_Reserve(int n) {
    ind_ctype_AbsReserve(_db.ind_ctype_n + n);
}

// --- acr_nav.FDb.ind_ctype.AbsReserve
// Reserve enough room for exacty N elements. Return success code.
void acr_nav::ind_ctype_AbsReserve(int n) {
    u32 old_nbuckets = _db.ind_ctype_buckets_n;
    u32 new_nelems   = n;
    // # of elements has to be roughly equal to the number of buckets
    if (new_nelems > old_nbuckets) {
        int new_nbuckets = i32_Max(algo::BumpToPow2(new_nelems), u32(4));
        u32 old_size = old_nbuckets * sizeof(acr_nav::FCtype*);
        u32 new_size = new_nbuckets * sizeof(acr_nav::FCtype*);
        // allocate new array. we don't use Realloc since copying is not needed and factor of 2 probably
        // means new memory will have to be allocated anyway
        acr_nav::FCtype* *new_buckets = (acr_nav::FCtype**)algo_lib::malloc_AllocMem(new_size);
        if (UNLIKELY(!new_buckets)) {
            FatalErrorExit("acr_nav.out_of_memory  field:acr_nav.FDb.ind_ctype");
        }
        memset(new_buckets, 0, new_size); // clear pointers
        // rehash all entries
        for (int i = 0; i < _db.ind_ctype_buckets_n; i++) {
            acr_nav::FCtype* elem = _db.ind_ctype_buckets_elems[i];
            while (elem) {
                acr_nav::FCtype &row        = *elem;
                acr_nav::FCtype* next       = row.ind_ctype_next;
                u32 index          = row.ind_ctype_hashval & (new_nbuckets-1);
                row.ind_ctype_next     = new_buckets[index];
                new_buckets[index] = &row;
                elem               = next;
            }
        }
        // free old array
        algo_lib::malloc_FreeMem(_db.ind_ctype_buckets_elems, old_size);
        _db.ind_ctype_buckets_elems = new_buckets;
        _db.ind_ctype_buckets_n = new_nbuckets;
    }
}

