// --- acr_nav.FDb.field.Alloc
// Allocate memory for new default row.
// If out of memory, process is killed.
acr_nav::FField& acr_nav::field_Alloc() {
    acr_nav::FField* row = field_AllocMaybe();
    if (UNLIKELY(row == NULL)) {
        FatalErrorExit("acr_nav.out_of_mem  field:acr_nav.FDb.field  comment:'Alloc failed'");
    }
    return *row;
}

// --- acr_nav.FDb.field.AllocMaybe
// Allocate memory for new element. If out of memory, return NULL.
acr_nav::FField* acr_nav::field_AllocMaybe() {
    acr_nav::FField *row = (acr_nav::FField*)field_AllocMem();
    if (row) {
        new (row) acr_nav::FField; // call constructor
    }
    return row;
}

// --- acr_nav.FDb.field.InsertMaybe
// Create new row from struct.
// Return pointer to new element, or NULL if insertion failed (due to out-of-memory, duplicate key, etc)
acr_nav::FField* acr_nav::field_InsertMaybe(const dmmeta::Field &value) {
    acr_nav::FField *row = &field_Alloc(); // if out of memory, process dies. if input error, return NULL.
    field_CopyIn(*row,const_cast<dmmeta::Field&>(value));
    bool ok = field_XrefMaybe(*row); // this may return false
    if (!ok) {
        field_RemoveLast(); // delete offending row, any existing xrefs are cleared
        row = NULL; // forget this ever happened
    }
    return row;
}

// --- acr_nav.FDb.field.AllocMem
// Allocate space for one element. If no memory available, return NULL.
void* acr_nav::field_AllocMem() {
    u64 new_nelems     = _db.field_n+1;
    // compute level and index on level
    u64 bsr   = algo::u64_BitScanReverse(new_nelems);
    u64 base  = u64(1)<<bsr;
    u64 index = new_nelems-base;
    void *ret = NULL;
    // if level doesn't exist yet, create it
    acr_nav::FField*  lev   = NULL;
    if (bsr < 32) {
        lev = _db.field_lary[bsr];
        if (!lev) {
            lev=(acr_nav::FField*)algo_lib::malloc_AllocMem(sizeof(acr_nav::FField) * (u64(1)<<bsr));
            _db.field_lary[bsr] = lev;
        }
    }
    // allocate element from this level
    if (lev) {
        _db.field_n = i32(new_nelems);
        ret = lev + index;
    }
    return ret;
}

// --- acr_nav.FDb.field.RemoveAll
// Remove all elements from Lary
void acr_nav::field_RemoveAll() {
    for (u64 n = _db.field_n; n>0; ) {
        n--;
        field_qFind(u64(n)).~FField(); // destroy last element
        _db.field_n = i32(n);
    }
}

// --- acr_nav.FDb.field.RemoveLast
// Delete last element of array. Do nothing if array is empty.
void acr_nav::field_RemoveLast() {
    u64 n = _db.field_n;
    if (n > 0) {
        n -= 1;
        field_qFind(u64(n)).~FField();
        _db.field_n = i32(n);
    }
}

// --- acr_nav.FDb.field.InputMaybe
static bool acr_nav::field_InputMaybe(dmmeta::Field &elem) {
    bool retval = true;
    retval = field_InsertMaybe(elem) != nullptr;
    return retval;
}

// --- acr_nav.FDb.field.XrefMaybe
// Insert row into all appropriate indices. If error occurs, store error
// in algo_lib::_db.errtext and return false. Caller must Delete or Unref such row.
bool acr_nav::field_XrefMaybe(acr_nav::FField &row) {
    bool retval = true;
    (void)row;
    acr_nav::FCtype* p_ctype = acr_nav::ind_ctype_Find(ctype_Get(row));
    if (UNLIKELY(!p_ctype)) {
        algo_lib::ResetErrtext() << "acr_nav.bad_xref  index:acr_nav.FDb.ind_ctype" << Keyval("key", ctype_Get(row));
        return false;
    }
    // field: save pointer to ctype
    if (true) { // user-defined insert condition
        row.p_ctype = p_ctype;
    }
    acr_nav::FCtype* p_arg = acr_nav::ind_ctype_Find(row.arg);
    if (UNLIKELY(!p_arg)) {
        algo_lib::ResetErrtext() << "acr_nav.bad_xref  index:acr_nav.FDb.ind_ctype" << Keyval("key", row.arg);
        return false;
    }
    // field: save pointer to arg
    if (true) { // user-defined insert condition
        row.p_arg = p_arg;
    }
    acr_nav::FReftype* p_reftype = acr_nav::ind_reftype_Find(row.reftype);
    if (UNLIKELY(!p_reftype)) {
        algo_lib::ResetErrtext() << "acr_nav.bad_xref  index:acr_nav.FDb.ind_reftype" << Keyval("key", row.reftype);
        return false;
    }
    // field: save pointer to reftype
    if (true) { // user-defined insert condition
        row.p_reftype = p_reftype;
    }
    // insert field into index ind_field
    if (true) { // user-defined insert condition
        bool success = ind_field_InsertMaybe(row);
        if (UNLIKELY(!success)) {
            ch_RemoveAll(algo_lib::_db.errtext);
            algo_lib::_db.errtext << "acr_nav.duplicate_key  xref:acr_nav.FDb.ind_field"; // check for duplicate key
            return false;
        }
    }
    // insert field into index c_field
    if (true) { // user-defined insert condition
        c_field_Insert(*p_ctype, row);
    }
    // insert field into index c_field_arg
    if (true) { // user-defined insert condition
        c_field_arg_Insert(*p_arg, row);
    }
    return retval;
}

