// --- acr_nav.FDb.navaction.XrefMaybe
// Insert row into all appropriate indices. If error occurs, store error
// in algo_lib::_db.errtext and return false. Caller must Delete or Unref such row.
bool acr_nav::navaction_XrefMaybe(acr_nav::FNavaction &row) {
    bool retval = true;
    (void)row;
    // insert navaction into index ind_navaction
    if (true) { // user-defined insert condition
        bool success = ind_navaction_InsertMaybe(row);
        if (UNLIKELY(!success)) {
            ch_RemoveAll(algo_lib::_db.errtext);
            algo_lib::_db.errtext << "acr_nav.duplicate_key  xref:acr_nav.FDb.ind_navaction"; // check for duplicate key
            return false;
        }
    }
    return retval;
}

// --- acr_nav.FDb.ind_navaction.Find
// Find row by key. Return NULL if not found.
acr_nav::FNavaction* acr_nav::ind_navaction_Find(const algo::strptr& key) {
    u32 index = algo::Smallstr50_Hash(0, key) & (_db.ind_navaction_buckets_n - 1);
    acr_nav::FNavaction *ret = _db.ind_navaction_buckets_elems[index];
    for (; ret && !((*ret).navaction == key); ret = ret->ind_navaction_next) {
    }
    return ret;
}

// --- acr_nav.FDb.ind_navaction.FindX
// Look up row by key and return reference. Throw exception if not found
acr_nav::FNavaction& acr_nav::ind_navaction_FindX(const algo::strptr& key) {
    acr_nav::FNavaction* ret = ind_navaction_Find(key);
    vrfy(ret, tempstr() << "acr_nav.key_error  table:ind_navaction  key:'"<<key<<"'  comment:'key not found'");
    return *ret;
}

// --- acr_nav.FDb.ind_navaction.GetOrCreate
// Find row by key. If not found, create and x-reference a new row with with this key.
acr_nav::FNavaction& acr_nav::ind_navaction_GetOrCreate(const algo::strptr& key) {
    acr_nav::FNavaction* ret = ind_navaction_Find(key);
    if (!ret) { //  if memory alloc fails, process dies; if insert fails, function returns NULL.
        ret         = &navaction_Alloc();
        (*ret).navaction = key;
        bool good = navaction_XrefMaybe(*ret);
        if (!good) {
            navaction_RemoveLast(); // delete offending row, any existing xrefs are cleared
            ret = NULL;
        }
    }
    vrfy(ret, tempstr() << "acr_nav.create_error  table:ind_navaction  key:'"<<key<<"'  comment:'bad xref'");
    return *ret;
}

// --- acr_nav.FDb.ind_navaction.InsertMaybe
// Insert row into hash table. Return true if row is reachable through the hash after the function completes.
bool acr_nav::ind_navaction_InsertMaybe(acr_nav::FNavaction& row) {
    bool retval = true; // if already in hash, InsertMaybe returns true
    if (LIKELY(row.ind_navaction_next == (acr_nav::FNavaction*)-1)) {// check if in hash already
        row.ind_navaction_hashval = algo::Smallstr50_Hash(0, row.navaction);
        ind_navaction_Reserve(1);
        u32 index = row.ind_navaction_hashval & (_db.ind_navaction_buckets_n - 1);
        acr_nav::FNavaction* *prev = &_db.ind_navaction_buckets_elems[index];
        do {
            acr_nav::FNavaction* ret = *prev;
            if (!ret) { // exit condition 1: reached the end of the list
                break;
            }
            if ((*ret).navaction == row.navaction) { // exit condition 2: found matching key
                retval = false;
                break;
            }
            prev = &ret->ind_navaction_next;
        } while (true);
        if (retval) {
            row.ind_navaction_next = *prev;
            _db.ind_navaction_n++;
            *prev = &row;
        }
    }
    return retval;
}

// --- acr_nav.FDb.ind_navaction.Remove
// Remove reference to element from hash index. If element is not in hash, do nothing
void acr_nav::ind_navaction_Remove(acr_nav::FNavaction& row) {
    if (LIKELY(row.ind_navaction_next != (acr_nav::FNavaction*)-1)) {// check if in hash already
        u32 index = row.ind_navaction_hashval & (_db.ind_navaction_buckets_n - 1);
        acr_nav::FNavaction* *prev = &_db.ind_navaction_buckets_elems[index]; // addr of pointer to current element
        while (acr_nav::FNavaction *next = *prev) {                          // scan the collision chain for our element
            if (next == &row) {        // found it?
                *prev = next->ind_navaction_next; // unlink (singly linked list)
                _db.ind_navaction_n--;
                row.ind_navaction_next = (acr_nav::FNavaction*)-1;// not-in-hash
                break;
            }
            prev = &next->ind_navaction_next;
        }
    }
}

// --- acr_nav.FDb.ind_navaction.Reserve
// Reserve enough room in the hash for N more elements. Return success code.
void acr_nav::ind_navaction_Reserve(int n) {
    ind_navaction_AbsReserve(_db.ind_navaction_n + n);
}

// --- acr_nav.FDb.ind_navaction.AbsReserve
// Reserve enough room for exacty N elements. Return success code.
void acr_nav::ind_navaction_AbsReserve(int n) {
    u32 old_nbuckets = _db.ind_navaction_buckets_n;
    u32 new_nelems   = n;
    // # of elements has to be roughly equal to the number of buckets
    if (new_nelems > old_nbuckets) {
        int new_nbuckets = i32_Max(algo::BumpToPow2(new_nelems), u32(4));
        u32 old_size = old_nbuckets * sizeof(acr_nav::FNavaction*);
        u32 new_size = new_nbuckets * sizeof(acr_nav::FNavaction*);
        // allocate new array. we don't use Realloc since copying is not needed and factor of 2 probably
        // means new memory will have to be allocated anyway
        acr_nav::FNavaction* *new_buckets = (acr_nav::FNavaction**)algo_lib::malloc_AllocMem(new_size);
        if (UNLIKELY(!new_buckets)) {
            FatalErrorExit("acr_nav.out_of_memory  field:acr_nav.FDb.ind_navaction");
        }
        memset(new_buckets, 0, new_size); // clear pointers
        // rehash all entries
        for (int i = 0; i < _db.ind_navaction_buckets_n; i++) {
            acr_nav::FNavaction* elem = _db.ind_navaction_buckets_elems[i];
            while (elem) {
                acr_nav::FNavaction &row        = *elem;
                acr_nav::FNavaction* next       = row.ind_navaction_next;
                u32 index          = row.ind_navaction_hashval & (new_nbuckets-1);
                row.ind_navaction_next     = new_buckets[index];
                new_buckets[index] = &row;
                elem               = next;
            }
        }
        // free old array
        algo_lib::malloc_FreeMem(_db.ind_navaction_buckets_elems, old_size);
        _db.ind_navaction_buckets_elems = new_buckets;
        _db.ind_navaction_buckets_n = new_nbuckets;
    }
}

// --- acr_nav.FDb.keybind.Alloc
// Allocate memory for new default row.
// If out of memory, process is killed.
acr_nav::FKeybind& acr_nav::keybind_Alloc() {
    acr_nav::FKeybind* row = keybind_AllocMaybe();
    if (UNLIKELY(row == NULL)) {
        FatalErrorExit("acr_nav.out_of_mem  field:acr_nav.FDb.keybind  comment:'Alloc failed'");
    }
    return *row;
}

// --- acr_nav.FDb.keybind.AllocMaybe
// Allocate memory for new element. If out of memory, return NULL.
acr_nav::FKeybind* acr_nav::keybind_AllocMaybe() {
    acr_nav::FKeybind *row = (acr_nav::FKeybind*)keybind_AllocMem();
    if (row) {
        new (row) acr_nav::FKeybind; // call constructor
    }
    return row;
}

// --- acr_nav.FDb.keybind.InsertMaybe
// Create new row from struct.
// Return pointer to new element, or NULL if insertion failed (due to out-of-memory, duplicate key, etc)
acr_nav::FKeybind* acr_nav::keybind_InsertMaybe(const acr_navdb::Keybind &value) {
    acr_nav::FKeybind *row = &keybind_Alloc(); // if out of memory, process dies. if input error, return NULL.
    keybind_CopyIn(*row,const_cast<acr_navdb::Keybind&>(value));
    bool ok = keybind_XrefMaybe(*row); // this may return false
    if (!ok) {
        keybind_RemoveLast(); // delete offending row, any existing xrefs are cleared
        row = NULL; // forget this ever happened
    }
    return row;
}

// --- acr_nav.FDb.keybind.AllocMem
// Allocate space for one element. If no memory available, return NULL.
void* acr_nav::keybind_AllocMem() {
    u64 new_nelems     = _db.keybind_n+1;
    // compute level and index on level
    u64 bsr   = algo::u64_BitScanReverse(new_nelems);
    u64 base  = u64(1)<<bsr;
    u64 index = new_nelems-base;
    void *ret = NULL;
    // if level doesn't exist yet, create it
    acr_nav::FKeybind*  lev   = NULL;
    if (bsr < 32) {
        lev = _db.keybind_lary[bsr];
        if (!lev) {
            lev=(acr_nav::FKeybind*)algo_lib::malloc_AllocMem(sizeof(acr_nav::FKeybind) * (u64(1)<<bsr));
            _db.keybind_lary[bsr] = lev;
        }
    }
    // allocate element from this level
    if (lev) {
        _db.keybind_n = i32(new_nelems);
        ret = lev + index;
    }
    return ret;
}

// --- acr_nav.FDb.keybind.RemoveAll
// Remove all elements from Lary
void acr_nav::keybind_RemoveAll() {
    for (u64 n = _db.keybind_n; n>0; ) {
        n--;
        keybind_qFind(u64(n)).~FKeybind(); // destroy last element
        _db.keybind_n = i32(n);
    }
}

// --- acr_nav.FDb.keybind.RemoveLast
// Delete last element of array. Do nothing if array is empty.
void acr_nav::keybind_RemoveLast() {
    u64 n = _db.keybind_n;
    if (n > 0) {
        n -= 1;
        keybind_qFind(u64(n)).~FKeybind();
        _db.keybind_n = i32(n);
    }
}

