// Allocate memory for new default row.
// If out of memory, process is killed.
acr_nav::FNavmode& acr_nav::navmode_Alloc() {
    acr_nav::FNavmode* row = navmode_AllocMaybe();
    if (UNLIKELY(row == NULL)) {
        FatalErrorExit("acr_nav.out_of_mem  field:acr_nav.FDb.navmode  comment:'Alloc failed'");
    }
    return *row;
}

// --- acr_nav.FDb.navmode.AllocMaybe
// Allocate memory for new element. If out of memory, return NULL.
acr_nav::FNavmode* acr_nav::navmode_AllocMaybe() {
    acr_nav::FNavmode *row = (acr_nav::FNavmode*)navmode_AllocMem();
    if (row) {
        new (row) acr_nav::FNavmode; // call constructor
    }
    return row;
}

// --- acr_nav.FDb.navmode.InsertMaybe
// Create new row from struct.
// Return pointer to new element, or NULL if insertion failed (due to out-of-memory, duplicate key, etc)
acr_nav::FNavmode* acr_nav::navmode_InsertMaybe(const acr_navdb::Navmode &value) {
    acr_nav::FNavmode *row = &navmode_Alloc(); // if out of memory, process dies. if input error, return NULL.
    navmode_CopyIn(*row,const_cast<acr_navdb::Navmode&>(value));
    bool ok = navmode_XrefMaybe(*row); // this may return false
    if (!ok) {
        navmode_RemoveLast(); // delete offending row, any existing xrefs are cleared
        row = NULL; // forget this ever happened
    }
    return row;
}

// --- acr_nav.FDb.navmode.AllocMem
// Allocate space for one element. If no memory available, return NULL.
void* acr_nav::navmode_AllocMem() {
    u64 new_nelems     = _db.navmode_n+1;
    // compute level and index on level
    u64 bsr   = algo::u64_BitScanReverse(new_nelems);
    u64 base  = u64(1)<<bsr;
    u64 index = new_nelems-base;
    void *ret = NULL;
    // if level doesn't exist yet, create it
    acr_nav::FNavmode*  lev   = NULL;
    if (bsr < 32) {
        lev = _db.navmode_lary[bsr];
        if (!lev) {
            lev=(acr_nav::FNavmode*)algo_lib::malloc_AllocMem(sizeof(acr_nav::FNavmode) * (u64(1)<<bsr));
            _db.navmode_lary[bsr] = lev;
        }
    }
    // allocate element from this level
    if (lev) {
        _db.navmode_n = i32(new_nelems);
        ret = lev + index;
    }
    return ret;
}

// --- acr_nav.FDb.navmode.RemoveAll
// Remove all elements from Lary
void acr_nav::navmode_RemoveAll() {
    for (u64 n = _db.navmode_n; n>0; ) {
        n--;
        navmode_qFind(u64(n)).~FNavmode(); // destroy last element
        _db.navmode_n = i32(n);
    }
}

// --- acr_nav.FDb.navmode.RemoveLast
// Delete last element of array. Do nothing if array is empty.
void acr_nav::navmode_RemoveLast() {
    u64 n = _db.navmode_n;
    if (n > 0) {
        n -= 1;
        navmode_qFind(u64(n)).~FNavmode();
        _db.navmode_n = i32(n);
    }
}

