    field.p_reftype = NULL;
    field.ctype_c_field_in_ary = bool(false);
    field.ctype_c_field_arg_in_ary = bool(false);
    field.ind_field_next = (acr_nav::FField*)-1; // (acr_nav.FDb.ind_field) not-in-hash
