// --- acr_nav.FViewmode..Uninit
void acr_nav::FViewmode_Uninit(acr_nav::FViewmode& viewmode) {
    acr_nav::FViewmode &row = viewmode; (void)row;
    ind_viewmode_Remove(row); // remove viewmode from index ind_viewmode

    // acr_nav.FViewmode.preview_nav.Uninit (Tary)  //Navigable columns in current preview
    // remove all elements from acr_nav.FViewmode.preview_nav
    preview_nav_RemoveAll(viewmode);
    // free memory for Tary acr_nav.FViewmode.preview_nav
    algo_lib::malloc_FreeMem(viewmode.preview_nav_elems, sizeof(acr_nav::PreviewNavCol)*viewmode.preview_nav_max); // (acr_nav.FViewmode.preview_nav)

    // acr_nav.FViewmode.cspan.Uninit (Tary)  //Color spans for line-mode highlighting
    // remove all elements from acr_nav.FViewmode.cspan
    cspan_RemoveAll(viewmode);
    // free memory for Tary acr_nav.FViewmode.cspan
    algo_lib::malloc_FreeMem(viewmode.cspan_elems, sizeof(acr_nav::LineColorSpan)*viewmode.cspan_max); // (acr_nav.FViewmode.cspan)

    // acr_nav.FViewmode.line.Uninit (Tary)  //Preformatted content lines (has_fields:N modes)
    // remove all elements from acr_nav.FViewmode.line
    line_RemoveAll(viewmode);
    // free memory for Tary acr_nav.FViewmode.line
    algo_lib::malloc_FreeMem(viewmode.line_elems, sizeof(algo::cstring)*viewmode.line_max); // (acr_nav.FViewmode.line)
}

// --- acr_nav.FieldId.value.ToCstr
// Convert numeric value of field to one of predefined string constants.
// If string is found, return a static C string. Otherwise, return NULL.
const char* acr_nav::value_ToCstr(const acr_nav::FieldId& parent) {
    const char *ret = NULL;
    switch(value_GetEnum(parent)) {
        case acr_nav_FieldId_screenshot    : ret = "screenshot";  break;
        case acr_nav_FieldId_key           : ret = "key";  break;
        case acr_nav_FieldId_term_hei      : ret = "term_hei";  break;
        case acr_nav_FieldId_term_wid      : ret = "term_wid";  break;
        case acr_nav_FieldId_value         : ret = "value";  break;
    }
    return ret;
}

// --- acr_nav.FieldId.value.Print
// Convert value to a string. First, attempt conversion to a known string.
// If no string matches, print value as a numeric value.
void acr_nav::value_Print(const acr_nav::FieldId& parent, algo::cstring &lhs) {
    const char *strval = value_ToCstr(parent);
    if (strval) {
        lhs << strval;
    } else {
        lhs << parent.value;
    }
}

// --- acr_nav.FieldId.value.SetStrptrMaybe
// Convert string to field.
// If the string is invalid, do not modify field and return false.
// In case of success, return true
bool acr_nav::value_SetStrptrMaybe(acr_nav::FieldId& parent, algo::strptr rhs) {
    bool ret = false;
    switch (elems_N(rhs)) {
        case 3: {
            switch (u64(algo::ReadLE16(rhs.elems))|(u64(rhs[2])<<16)) {
                case LE_STR3('k','e','y'): {
                    value_SetEnum(parent,acr_nav_FieldId_key); ret = true; break;
                }
            }
            break;
        }
        case 5: {
            switch (u64(algo::ReadLE32(rhs.elems))|(u64(rhs[4])<<32)) {
                case LE_STR5('v','a','l','u','e'): {
                    value_SetEnum(parent,acr_nav_FieldId_value); ret = true; break;
                }
            }
            break;
        }
        case 8: {
            switch (algo::ReadLE64(rhs.elems)) {
                case LE_STR8('t','e','r','m','_','h','e','i'): {
                    value_SetEnum(parent,acr_nav_FieldId_term_hei); ret = true; break;
                }
                case LE_STR8('t','e','r','m','_','w','i','d'): {
                    value_SetEnum(parent,acr_nav_FieldId_term_wid); ret = true; break;
                }
            }
            break;
        }
        case 10: {
            switch (algo::ReadLE64(rhs.elems)) {
                case LE_STR8('s','c','r','e','e','n','s','h'): {
                    if (memcmp(rhs.elems+8,"ot",2)==0) { value_SetEnum(parent,acr_nav_FieldId_screenshot); ret = true; break; }
                    break;
                }
            }
            break;
        }
    }
    return ret;
}

// --- acr_nav.FieldId.value.SetStrptr
// Convert string to field.
// If the string is invalid, set numeric value to DFLT
void acr_nav::value_SetStrptr(acr_nav::FieldId& parent, algo::strptr rhs, acr_nav_FieldIdEnum dflt) {
    if (!value_SetStrptrMaybe(parent,rhs)) value_SetEnum(parent,dflt);
}

// --- acr_nav.FieldId.value.ReadStrptrMaybe
// Convert string to field. Return success value
bool acr_nav::value_ReadStrptrMaybe(acr_nav::FieldId& parent, algo::strptr rhs) {
    bool retval = false;
    retval = value_SetStrptrMaybe(parent,rhs); // try symbol conversion
    if (!retval) { // didn't work? try reading as underlying type
        retval = i32_ReadStrptrMaybe(parent.value,rhs);
    }
    return retval;
}

// --- acr_nav.FieldId..ReadStrptrMaybe
// Read fields of acr_nav::FieldId from an ascii string.
// The format of the string is the format of the acr_nav::FieldId's only field
bool acr_nav::FieldId_ReadStrptrMaybe(acr_nav::FieldId &parent, algo::strptr in_str) {
    bool retval = true;
    retval = retval && value_ReadStrptrMaybe(parent, in_str);
    return retval;
}

