        case acr_nav_TableId_dmmeta_Ctype  : ret = "dmmeta.Ctype";  break;
        case acr_nav_TableId_acr_navdb_Detailsrc: ret = "acr_navdb.Detailsrc";  break;
        case acr_nav_TableId_dmmeta_Field  : ret = "dmmeta.Field";  break;
