// --- acr_nav...SizeCheck
inline static void acr_nav::SizeCheck() {
}

// --- acr_nav...StaticCheck
void acr_nav::StaticCheck() {
    algo_assert(sizeof(acr_nav::navaction_step_hook) == 8); // csize:acr_nav.navaction_step_hook
    algo_assert(sizeof(acr_nav::viewmode_ensure_content_hook) == 8); // csize:acr_nav.viewmode_ensure_content_hook
    algo_assert(_offset_of(acr_nav::FieldId, value) + sizeof(((acr_nav::FieldId*)0)->value) == sizeof(acr_nav::FieldId));
}

// --- acr_nav...main
int main(int argc, char **argv) {
    try {
        lib_json::FDb_Init();
        algo_lib::FDb_Init();
        acr_nav::FDb_Init();
        algo_lib::_db.argc = argc;
        algo_lib::_db.argv = argv;
        algo_lib::IohookInit();
        algo_lib::_db.clock = algo::CurrSchedTime(); // initialize clock
        acr_nav::ReadArgv(); // dmmeta.main:acr_nav
        acr_nav::Main(); // user-defined main
    } catch(algo_lib::ErrorX &x) {
        prerr("acr_nav.error  " << x); // there may be additional hints in DetachBadTags
        algo_lib::_db.exit_code = 1;
    }
    if (algo_lib::_db.last_signal) {
        algo_lib::_db.exit_code = 1;
    }
    try {
        acr_nav::FDb_Uninit();
        algo_lib::FDb_Uninit();
        lib_json::FDb_Uninit();
    } catch(algo_lib::ErrorX &) {
        // don't print anything, might crash
        algo_lib::_db.exit_code = 1;
    }
    // only the lower 1 byte makes it to the outside world
    (void)i32_UpdateMin(algo_lib::_db.exit_code,255);
    return algo_lib::_db.exit_code;
}

